questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: find the mistake in a perpendicular bisector construction. er 1: radius not more than half of AB; 2: radius changed for B; 3: wrong points joined. Source: original. */
L: rand([6,7,8,9,10]);
er: 1+rand(3);
R1: if is(er=1) then L/2-rand([1,3/2]) else L/2+rand([1,3/2,2]);
R2: R1+rand([1,3/2]);
RB: if is(er=2) then R2 else R1;
nm: rand([["Wanjiru","She"],["Otieno","He"],["Chebet","She"],["Kamau","He"],["Achieng","She"],["Mutua","He"]]);
o1: [["s1",false,"Step 1"],["s2",is(er=1),"Step 2"],["s3",false,"Step 3"],["s4",is(er=2),"Step 4"],["s5",is(er=3),"Step 5"]];
o2: [["ok",false,"Nothing: the construction is correct"],["meet",is(er=1),"The arcs from A and B do not meet"],["mid",is(er=2),"The line crosses AB at right angles, but not at its midpoint"],["perp",is(er=3),"The line does not cross AB at right angles"]];
ta1: ["s2","s4","s5"][er];
ta2: ["meet","mid","perp"][er];
/* diagnostic step: Step 5 blamed when the arcs are wrong (er 1, 2); Step 2 blamed when the joining is wrong (er 3) */
dg1: ["s5","s5","s2"][er];
gw1: ["s4","s2","s4"][er];
wc2: first(sublist(["meet","mid","perp"], lambda([z], is(z#ta2))));
/* the aria-label says what this variant's drawing shows */
arl: sconcat("The construction drawn exactly as the steps are written: segment AB with arcs drawn from A and from B above and below it. ",
  ["The arcs from A do not reach the arcs from B, so they do not cross and no line is drawn.",
   "The arcs cross at two points, one above and one below AB, both nearer to one end than the other; the line joining them is drawn.",
   "The arcs cross above and below AB; a line is drawn from the crossing point above AB to B."][er]);
